function isTyping(el) {
  if (!el) return false;
  if (el.isContentEditable || el.tagName === "TEXTAREA") return true;
  return el.tagName === "INPUT" && !["range", "checkbox", "radio", "button", "submit", "color", "file"].includes((el.type || "").toLowerCase());
}
